function getItemDisplayName(itemId, quality = 'base') {
  const item = ITEM_DISPLAY_NAMES[itemId];
  if (!item) return itemId;
  return item[quality] || item.base || itemId;
}

module.exports = { ITEM_DISPLAY_NAMES, getItemDisplayName };

