    // --- ./controllers/screenTransitionController.js ---
    modules['./controllers/screenTransitionController.js'] = function(module, exports, require) {
/**
 * Lightweight screen transition state.
 *
 * Rendering is still synchronous; this controller only annotates the freshly
 * rendered screen so CSS can provide a consistent entrance feel.
 */

function createScreenTransitionController() {
  let lastKey = '';

  function getScreenKey(session) {
    if (!session) return 'unknown';
    if (session.phase === 'MAIN_GAME') return `${session.phase}:${session.subPhase || ''}`;
    return session.phase || 'unknown';
  }

  function getTransitionKind(previousKey, nextKey) {
    if (!previousKey) return 'boot';
    if (previousKey === nextKey) return '';
    if (previousKey === 'MAIN_GAME:AFTER_CLOSE' && nextKey === 'MAIN_GAME:BEFORE_OPEN') return '';
    if (nextKey === 'OPENING') return 'lantern';
    if (nextKey === 'HEROINE_SELECT') return 'sand';
    if (nextKey === 'MAIN_GAME:BEFORE_OPEN') return 'curtain';
    if (nextKey === 'MAIN_GAME:QUIZ') return 'counter';
    if (nextKey === 'MAIN_GAME:TURN_RESULT') return 'ledger';
    if (nextKey === 'ENDING') return 'lantern';
    return 'soft';
  }

  function beforeRender(session) {
    const nextKey = getScreenKey(session);
    const previousKey = lastKey;
    const changed = previousKey !== nextKey;
    if (changed) lastKey = nextKey;
    return {
      changed,
      from: previousKey,
      key: nextKey,
      kind: getTransitionKind(previousKey, nextKey)
    };
  }

  function apply(container, transition) {
    if (!container || !transition?.changed || !transition.kind) return;
    const screen = container.querySelector('[data-screen]');
    if (!screen) return;

    screen.setAttribute('data-transition-kind', transition.kind);
    screen.setAttribute('data-transition-from', transition.from || 'none');
    screen.classList.remove('screen-enter');
    void screen.offsetWidth;
    screen.classList.add('screen-enter');
  }

  return {
    beforeRender,
    apply
  };
}

module.exports = {
  createScreenTransitionController
};

    };

    // --- ./controllers/turnTransitionController.js ---
    modules['./controllers/turnTransitionController.js'] = function(module, exports, require) {
/**
 * Turn transition overlay controller.
 *
 * Owns transition timers and overlay lifecycle. It intentionally receives the
 * GameController instance so this extraction stays behavior-preserving.
 */

function createTurnTransitionController(controller) {
  const state = {
    timerId: null,
    tickTimerIds: [],
    callback: null,
    finishing: false,
    fadeOutMs: null
  };

  function play(callback, mode = 'next') {
    if (controller.uiState.turnTransitionActive) return;

    controller.uiState.turnTransitionActive = true;
    state.callback = callback;
    state.tickTimerIds = [];
    state.finishing = false;

    const viewport = document.getElementById('game-viewport') || controller.container;
    const oldOverlay = viewport.querySelector('.turn-transition-overlay');
    if (oldOverlay) oldOverlay.remove();

    const nextTurn = Math.min(controller.totalTurns, controller.session.turn + 1);
    const isEnding = mode === 'ending';
    const title = isEnding ? '終幕へ' : `第${nextTurn}ターンへ`;
    const subtitle = isEnding ? '星が静かに幕を下ろす' : '夜が巡り、朝の光が店先を照らす';

    const overlay = document.createElement('div');
    overlay.className = `turn-transition-overlay is-entering ${isEnding ? 'is-ending' : 'is-next-turn'}`;
    overlay.setAttribute('data-action', 'skip-turn-transition');
    overlay.setAttribute('tabindex', '-1');
    overlay.setAttribute('role', 'presentation');
    overlay.innerHTML = `
      <div class="turn-transition-darkness" aria-hidden="true"></div>
      <div class="turn-transition-clock-wrap" aria-hidden="true">
        <img class="turn-transition-clock" src="images/ui/clock.webp" alt="" draggable="false">
        <div class="turn-transition-clock-glow"></div>
        <div class="turn-transition-clock-shadow"></div>
      </div>
      <div class="turn-transition-copy">
        <p class="turn-transition-label">${title}</p>
        <p class="turn-transition-subtitle">${subtitle}</p>
        <p class="turn-transition-skip">クリックでスキップ</p>
      </div>
    `;
    viewport.appendChild(overlay);

    // The overlay itself is fully black from the first frame. Only the clock
    // ornaments animate in, so the previous turn's final still/standing image
    // can never be visible behind the turn handoff.
    window.requestAnimationFrame(() => {
      overlay.classList.remove('is-entering');
    });

    const fadeInMs = 1000;
    const introHoldMs = 500;
    const stepMs = 1000;
    const restMs = 200;
    const stepCount = 5;
    const postHoldMs = 500;
    const fadeOutMs = 1000;
    const rotateStartMs = fadeInMs + introHoldMs;
    const rotationRunMs = (stepMs * stepCount) + (restMs * (stepCount - 1));
    const exitStartMs = rotateStartMs + rotationRunMs + postHoldMs;

    Array.from({ length: stepCount }, (_, index) => rotateStartMs + (index * (stepMs + restMs))).forEach((delay) => {
      const timerId = window.setTimeout(() => {
        if (controller.uiState.turnTransitionActive && !state.finishing) controller.playSfx('turnClockTick');
      }, delay);
      state.tickTimerIds.push(timerId);
    });

    const completeSfxTimerId = window.setTimeout(() => {
      if (controller.uiState.turnTransitionActive && !state.finishing) controller.playSfx('turnClockComplete');
    }, rotateStartMs + rotationRunMs);
    state.tickTimerIds.push(completeSfxTimerId);

    state.timerId = window.setTimeout(() => {
      finish(false);
    }, exitStartMs);

    state.fadeOutMs = fadeOutMs;
  }

  function finish(skip = false) {
    if (!controller.uiState.turnTransitionActive || state.finishing) return;
    state.finishing = true;

    if (state.timerId) {
      window.clearTimeout(state.timerId);
      state.timerId = null;
    }

    if (Array.isArray(state.tickTimerIds)) {
      state.tickTimerIds.forEach((timerId) => window.clearTimeout(timerId));
      state.tickTimerIds = [];
    }

    const overlay = document.querySelector('.turn-transition-overlay');
    const fadeMs = skip ? 260 : (state.fadeOutMs || 1000);

    const callback = state.callback;
    state.callback = null;

    const cleanup = () => {
      state.finishing = false;
      state.fadeOutMs = null;
      controller.uiState.turnTransitionActive = false;
      if (overlay) overlay.remove();
    };

    if (!overlay) {
      if (typeof callback === 'function') callback();
      cleanup();
      return;
    }

    // Keep a fully black handoff veil while the next game state is rendered.
    // Fast-forwarding the clock may shorten the blackout, but it must never fade
    // the overlay out before callback/update or the previous day scene flashes.
    overlay.classList.remove('is-entering');
    overlay.classList.add('is-handoff');

    window.requestAnimationFrame(() => {
      if (typeof callback === 'function') callback();
      window.requestAnimationFrame(() => {
        overlay.classList.add('is-exiting');
        if (skip) overlay.classList.add('is-skipping');
        state.timerId = window.setTimeout(() => {
          state.timerId = null;
          cleanup();
        }, fadeMs);
      });
    });
  }

  return {
    play,
    finish
  };
}

module.exports = {
  createTurnTransitionController
};

    };

    // --- ./controllers/typewriterController.js ---
    modules['./controllers/typewriterController.js'] = function(module, exports, require) {
/**
 * Typewriter text controller.
 *
 * Keeps text reveal timers out of the main GameController while preserving the
 * same public operations: start, finish, clear, and isActive.
 */

function createTypewriterController(options = {}) {
  const getDelayMs = typeof options.getDelayMs === 'function' ? options.getDelayMs : () => 32;
  const isInstant = typeof options.isInstant === 'function' ? options.isInstant : () => false;

  const state = {
    fullText: '',
    visibleText: '',
    index: 0,
    timerId: null,
    isTyping: false,
    targetEl: null
  };

  function clear() {
    if (state.timerId) {
      clearTimeout(state.timerId);
      state.timerId = null;
    }
    state.isTyping = false;
  }

  function finish() {
    clear();
    state.index = state.fullText.length;
    state.isTyping = false;
    if (state.targetEl) {
      state.targetEl.textContent = state.fullText;
    }
  }

  function tick() {
    const delay = getDelayMs();
    state.timerId = setTimeout(() => {
      state.index++;
      state.visibleText = state.fullText.substring(0, state.index);
      if (state.targetEl) {
        state.targetEl.textContent = state.visibleText;
      }

      if (state.index < state.fullText.length) {
        tick();
      } else {
        state.isTyping = false;
      }
    }, delay);
  }

  function start(text, el) {
    clear();
    state.fullText = text;
    state.targetEl = el;
    state.index = 0;
    state.isTyping = true;

    if (isInstant()) {
      finish();
      return;
    }

    tick();
  }

  function isActive() {
    return state.isTyping;
  }

  return {
    start,
    finish,
    clear,
    isActive
  };
}

module.exports = {
  createTypewriterController
};

    };

